use serde::{Deserialize, Serialize};
use uuid::Uuid;

pub(super) const DEFAULT_PAGE: i64 = 1;
pub(super) const DEFAULT_PAGE_SIZE: i64 = 20;
pub(super) const MAX_PAGE_SIZE: i64 = 100;
/// Keeps `(page - 1) * page_size` far from overflow.
pub(super) const MAX_PAGE: i64 = 100_000;

/// `website` is a honeypot that real candidates never see or fill.
/// `submission_id` is generated by the client so a retried POST is idempotent.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct PublicSubmissionRequest {
    pub(super) submission_id: Uuid,
    pub(super) test_key: String,
    pub(super) question_set_version: i32,
    pub(super) candidate: CandidateInput,
    pub(super) answers: SubmissionAnswers,
    pub(super) started_at: Option<String>,
    #[serde(default)]
    pub(super) website: Option<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct CandidateInput {
    pub(super) name: String,
    pub(super) contact: String,
    pub(super) school_and_grade: String,
    #[serde(default)]
    pub(super) major: String,
    #[serde(default)]
    pub(super) weekly_availability: String,
    #[serde(default)]
    pub(super) earliest_start: String,
    #[serde(default)]
    pub(super) portfolio_url: Option<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct SubmissionAnswers {
    pub(super) project: String,
    #[serde(default)]
    pub(super) video_task_code: String,
    #[serde(default)]
    pub(super) video_task_notes: String,
    pub(super) ai_usage: String,
    #[serde(default)]
    pub(super) remix_plan: String,
    #[serde(default)]
    pub(super) workflow: String,
    #[serde(default)]
    pub(super) workflow_rules: String,
    #[serde(default)]
    pub(super) agent_plan: String,
    #[serde(default)]
    pub(super) video_practice: String,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct PublicSubmissionResponse {
    pub(super) submission_id: Uuid,
    pub(super) submitted_at: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct SubmissionListQuery {
    pub(super) page: Option<i64>,
    pub(super) page_size: Option<i64>,
}

#[derive(Debug, Clone, Copy, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub(super) struct ReviewScores {
    pub(super) project: i16,
    pub(super) async_logic: i16,
    pub(super) robustness: i16,
    pub(super) design: i16,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum ReviewVerdict {
    Advance,
    Hold,
    Reject,
}

impl ReviewVerdict {
    pub(super) fn as_str(self) -> &'static str {
        match self {
            Self::Advance => "advance",
            Self::Hold => "hold",
            Self::Reject => "reject",
        }
    }
}

/// `verdict` is one of `advance`, `hold`, `reject`.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct ReviewSummary {
    pub(super) scores: ReviewScores,
    pub(super) total: i16,
    pub(super) verdict: String,
    pub(super) note: Option<String>,
    pub(super) reviewed_by: Option<String>,
    pub(super) reviewed_at: String,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct SubmissionListItem {
    pub(super) submission_id: Uuid,
    pub(super) candidate_name: String,
    pub(super) school_and_grade: String,
    pub(super) submitted_at: String,
    pub(super) duration_seconds: Option<i64>,
    pub(super) review: Option<ReviewSummary>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct SubmissionListResponse {
    pub(super) items: Vec<SubmissionListItem>,
    pub(super) total: i64,
    pub(super) page: i64,
    pub(super) page_size: i64,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct SubmissionDetail {
    pub(super) submission_id: Uuid,
    pub(super) test_key: String,
    pub(super) question_set_version: i32,
    pub(super) candidate: CandidateInput,
    pub(super) answers: SubmissionAnswers,
    pub(super) started_at: Option<String>,
    pub(super) submitted_at: String,
    pub(super) duration_seconds: Option<i64>,
    pub(super) review: Option<ReviewSummary>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct SaveReviewRequest {
    pub(super) scores: ReviewScores,
    #[serde(default)]
    pub(super) note: Option<String>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct RubricDimension {
    pub(super) key: String,
    pub(super) label: String,
    pub(super) max: i16,
    pub(super) guidance: String,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct RubricThresholds {
    pub(super) advance_min: i16,
    pub(super) hold_min: i16,
    pub(super) video_task_min: i16,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct RubricResponse {
    pub(super) dimensions: Vec<RubricDimension>,
    pub(super) thresholds: RubricThresholds,
    pub(super) video_task_checkpoints: Vec<String>,
    pub(super) strong_signals: String,
    pub(super) average_signals: String,
    pub(super) weak_signals: String,
    pub(super) interview_follow_up: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct RubricQuery {
    pub(super) question_set_version: Option<i32>,
}
